def collapse_whitespace(s: str) -> str:
    """Collapse runs of ASCII whitespace into a single space and strip ends."""
    result = []
    prev_was_ws = False
    for ch in s:
        # ASCII whitespace: space, tab, LF, CR, vertical tab, form feed
        if ch in (' ', '\t', '\n', '\r', '\x0b', '\x0c'):
            if not prev_was_ws:
                result.append(' ')
                prev_was_ws = True
        else:
            result.append(ch)
            prev_was_ws = False
    # Strip leading/trailing spaces
    while result and result[0] == ' ':
        result.pop(0)
    while result and result[-1] == ' ':
        result.pop()
    return ''.join(result)
